  } else {
    console.error(`\nVerification failed: Organization with id=${createdOrgId} not found in list.`);
    process.exit(1);
  }

  // Write org ID to file
  const outputPath = '/home/user/scalekit-orgs/org_id.txt';
  fs.writeFileSync(outputPath, createdOrgId, 'utf8');
  console.log(`\nOrg ID written to ${outputPath}: ${createdOrgId}`);
}

main().catch(err => {
  console.error('Error:', err);
